import csv
import io


def import_text(text, store, dry_run=False):
    parsed = []
    for row in csv.DictReader(io.StringIO(text)):
        sku = row['sku'].strip()
        name = row['name'].strip()
        qty = row['qty'].strip()
        if not sku or not name:
            raise ValueError('invalid row: SKU and name must be nonempty')
        if not qty.isdigit():
            raise ValueError('invalid row: quantity must contain only decimal digits')
        parsed.append({'sku': sku, 'name': name, 'qty': int(qty)})

    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in parsed:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

